import fs from 'fs';
import * as mod from './App.js';

const code = fs.readFileSync('/App.js', 'utf8');

test('declara favoriteFood com var', () => {
  expect(code).toMatch(/var\s+favoriteFood\s*=/);
});

test('favoriteFood é pizza', () => {
  expect(mod.favoriteFood).toBe('pizza');
});

import fs from 'fs';
import * as mod from './App.js';

const code = fs.readFileSync('/App.js', 'utf8');

test('declara numOfSlices com var', () => {
  expect(code).toMatch(/var\s+numOfSlices\s*=/);
});

test('numOfSlices é 8', () => {
  expect(mod.numOfSlices).toBe(8);
});

